//! Actions-only codec, shared durable intent/Unknown and descriptor regressions.
use super::*;
use n::{group_management::{self as gm,GroupWriteOperation as Op,NativeGroupManagementConfig as GPolicy,PublicProperty,PropertyValue},relation_journal::{RelationIntent,IntentAdmission,RelationConfiguration},group_management_store};
fn gpolicy()->GPolicy{GPolicy{set_properties:true,disband:true}}
fn props()->[PublicProperty<'static>;1]{[PublicProperty{key:"Name",value:PropertyValue::Text("private-group-name")} ]}
fn installed()->Fixture{let f=Fixture::new(true);f.temp.database.with_conn(group_management_store::initialize_schema).unwrap();f}
fn intent(f:&Fixture,nonce:&str,op:Op)->Result<IntentAdmission,&'static str>{let fields=props();let fields=if op==Op::SetProperties{fields.as_slice()}else{&[]};let m=Arc::new(RelationMessage::capture_management(&f.scope,b"1-2",op,fields,nonce,gpolicy())?);let config=Arc::new(f.temp.database.with_conn(|c|RelationConfiguration::capture(c,f.run.line_id(),1,Some(&f.scope)))?);RelationIntent::capture(f.temp.database.clone(),f.run.clone(),f.owner.clone(),f.scope.clone(),m,config,f.gate.clone(),Instant::now()+Duration::from_secs(30))}
fn bound(f:&Fixture,nonce:&str,op:Op)->(Arc<RelationIntent>,Arc<RelationAction>,Arc<RelationPermit>){let IntentAdmission::Fresh(i)=intent(f,nonce,op).unwrap()else{panic!("fresh")};let PreparedRelation::Fresh(a)=i.bind(f.backend.captured_im_binding().unwrap(),f.backend.captured_relation_identity().unwrap(),gpolicy()).unwrap()else{panic!("fresh write")};let p=a.permit(gpolicy()).unwrap();(i,a,p)}
fn gresult(f:&mut Fixture,id:i32,op:Op,accepted:bool)->n::rpc_relation_update::OwnedRelationReply{let mut w=Writer::new();w.boolean(accepted).unwrap();if op==Op::Disband{w.i64(i64::MIN).unwrap();w.i64(i64::MAX).unwrap();}w.bytes(b"").unwrap();f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(id,w.finish().expose_to_transport()),0).unwrap();f.backend.take_relation_replies().pop().unwrap()}
#[test]fn group_management_original_property_names_and_enums_are_exact_not_roles_or_json_wire(){for(key,values)in[("Type",vec!["DiscussionGroup","Group","LargeGroup","Room","LargeRoom"]),("UpdateMethod",vec!["Notify","Refresh","Mixed"]),("Permission",vec!["Manager","Member","Free","Pwd"]),("PropertyControl",vec!["Owner","Manager","Member"]) ]{for(i,value)in values.iter().enumerate(){let p=gm::property(&PublicProperty{key,value:PropertyValue::Number(i as u32)}).unwrap();assert_eq!(p.value,value.as_bytes());assert!(p.key.starts_with(b"Group.Org."));}assert!(gm::property(&PublicProperty{key,value:PropertyValue::Number(values.len()as u32)}).is_err());}assert_eq!(gm::property(&props()[0]).unwrap().key,b"Group.Org.Name");assert!(gm::property(&PublicProperty{key:"Type",value:PropertyValue::Text("1")}).is_err());}
#[test]fn group_management_codec_exact_setprops_and_disband_envelopes(){let bytes=gm::encode(b"1-2",Op::SetProperties,&props()).unwrap();assert_eq!(bytes.allocated_capacity(),gm::size(b"1-2",Op::SetProperties,&props()).unwrap());let mut r=Reader::versioned(bytes.expose_to_transport()).unwrap();assert_eq!(r.bytes().unwrap(),b"1-2");let p=r.properties().unwrap();assert_eq!(p.len(),1);assert_eq!(p[0].key,b"Group.Org.Name");assert_eq!(p[0].value,b"private-group-name");r.finish().unwrap();assert_eq!(gm::encode(b"1-2",Op::Disband,&[]).unwrap().expose_to_transport(),[0,0,1,0,0,0,0,0,3,b'1',b'-',b'2']);}
#[test]fn group_management_duplicate_after_key_mapping_and_invalid_shape_fail_before_allocation(){let f=installed();let duplicate=[PublicProperty{key:"Name",value:PropertyValue::Text("x")},PublicProperty{key:"Group.Org.Name",value:PropertyValue::Text("y")}];assert!(gm::size(b"1-2",Op::SetProperties,&duplicate).is_err());for id in [b"1_2".as_slice(),b"Org/1-2",b"1-0",b""]{assert!(gm::size(id,Op::Disband,&[]).is_err());}assert!(gm::size(b"1-2",Op::Disband,&props()).is_err());assert!(gm::size(b"1-2",Op::SetProperties,&[]).is_err());assert!(gm::property(&PublicProperty{key:"Name",value:PropertyValue::Text("x\0y")}).is_err());assert_eq!(f.scope.native_rpc_resources(),(0,0));}
#[test]fn group_management_policy_default_none_and_explicit_families_cannot_cross_admit(){assert!(GPolicy{set_properties:false,disband:false}.validate().is_err());assert!(!GPolicy{set_properties:true,disband:false}.admits(Op::Disband));let f=installed();let IntentAdmission::Fresh(i)=intent(&f,&"a".repeat(32),Op::Disband).unwrap()else{panic!()};assert!(i.bind(f.backend.captured_im_binding().unwrap(),f.backend.captured_relation_identity().unwrap(),policy()).is_err());assert!(i.bind(f.backend.captured_im_binding().unwrap(),f.backend.captured_relation_identity().unwrap(),GPolicy{set_properties:true,disband:false}).is_err());}
#[test]fn group_management_beforeawait_intent_blocks_membership_and_other_operation_before_any_id(){for op in [Op::SetProperties,Op::Disband]{let f=installed();let IntentAdmission::Fresh(_i)=intent(&f,&"a".repeat(32),op).unwrap()else{panic!()};let m=Arc::new(RelationMessage::capture(&f.scope,None,&[relation(b"1_2")],&[],&[],&"b".repeat(32),policy()).unwrap());let config=Arc::new(f.temp.database.with_conn(|c|RelationConfiguration::capture(c,f.run.line_id(),1,Some(&f.scope))).unwrap());assert_eq!(RelationIntent::capture(f.temp.database.clone(),f.run.clone(),f.owner.clone(),f.scope.clone(),m,config,f.gate.clone(),Instant::now()+Duration::from_secs(30)).err(),Some("app_account_relation_preparing"));assert_eq!(intent(&f,&"b".repeat(32),Op::Disband).err(),Some("app_account_relation_preparing"));let n:i64=f.temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_relation_writes",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(n,0);}}
#[test]fn group_management_cannot_bypass_unknown_membership_marker_with_new_nonce_or_other_group(){let f=installed();let _a=action(&f);assert_eq!(intent(&f,&"b".repeat(32),Op::SetProperties).err(),Some("app_account_relation_uncertain"));assert_eq!(state(&f),(0,None,None,None));}
#[test]fn group_management_same_nonce_different_operation_is_conflict_not_new_owner(){let f=installed();let IntentAdmission::Fresh(_i)=intent(&f,&"a".repeat(32),Op::Disband).unwrap()else{panic!()};assert_eq!(intent(&f,&"a".repeat(32),Op::SetProperties).err(),Some("app_account_relation_nonce_conflict"));}
#[test]fn group_management_matched_results_have_operation_specific_times_and_zero_member_counts(){for op in [Op::SetProperties,Op::Disband]{for accepted in [true,false]{let mut f=installed();let(_i,_a,p)=bound(&f,&"a".repeat(32),op);let frame=write(&mut f,&p);let rpc=decode_request(&frame.packets[0].expose_to_transport()[1..]).unwrap();assert_eq!(rpc.method,op.method().as_bytes());assert!(p.begin_write(frame.call_id));assert!(p.submitted());let r=gresult(&mut f,frame.call_id,op,accepted);let v=p.resolve(&r).unwrap();assert_eq!(v.state,if accepted{"confirmed"}else{"rejected"});assert_eq!((v.additions,v.updates,v.removals),(0,0,0));assert_eq!(v.management.as_ref().unwrap().operation,op.name());if op==Op::SetProperties{assert!(v.base_time.is_none()&&v.update_time.is_none());}else{assert_eq!(v.base_time.as_deref(),Some("-9223372036854775808"));assert_eq!(v.update_time.as_deref(),Some("9223372036854775807"));}let events=f.temp.database.get_recent_app_events(Some(f.run.line_id()),128).unwrap();assert_eq!(events.len(),1);assert_eq!(events[0].event_type,"app_voice.group_management_updated");assert!(f.scope.is_open());let body=serde_json::to_string(&v).unwrap();for secret in ["private-group-name","1-2","fixture-user","fixture-auth",&"a".repeat(32)]{assert!(!body.contains(secret));}}}}
#[test]fn group_management_queued_cancel_and_possible_write_cancel_use_shared_original_unknown_semantics(){for submitted in [false,true]{let mut f=installed();let(i,a,p)=bound(&f,&"a".repeat(32),Op::Disband);let frame=write(&mut f,&p);if submitted{assert!(p.begin_write(frame.call_id));assert!(p.submitted());}a.cancel();assert_eq!(state(&f).0,if submitted{0}else{3});assert_eq!(f.scope.is_open(),!submitted);drop(i);assert!(f.backend.take_relation_replies().is_empty());}}
#[test]fn group_management_descriptor_corruption_cannot_change_operation_or_terminal_result(){let mut f=installed();let(_i,_a,p)=bound(&f,&"a".repeat(32),Op::Disband);let frame=write(&mut f,&p);f.temp.database.with_conn(|c|c.execute("UPDATE app_voice_group_write_operations SET operation='set_properties',properties=1",[]).map_err(|_|"fixture")).unwrap();assert!(!p.begin_write(frame.call_id));assert!(!frame.packets[0].group_event_packet_current(Instant::now()));p.cancel();assert_eq!(state(&f).0,0);}
#[test]fn group_management_terminal_sql_failure_rolls_back_shared_unknown_row_and_event(){let mut f=installed();let(_i,_a,p)=bound(&f,&"a".repeat(32),Op::SetProperties);let frame=write(&mut f,&p);assert!(p.begin_write(frame.call_id));assert!(p.submitted());let r=gresult(&mut f,frame.call_id,Op::SetProperties,true);f.temp.database.with_conn(|c|c.execute_batch("CREATE TRIGGER fail_group_event BEFORE INSERT ON app_events WHEN NEW.event_type='app_voice.group_management_updated' BEGIN SELECT RAISE(ABORT,'fixture'); END").map_err(|_|"fixture")).unwrap();assert!(p.resolve(&r).is_err());assert_eq!(state(&f),(0,Some(frame.call_id),None,None));assert!(f.temp.database.get_recent_app_events(Some(f.run.line_id()),128).unwrap().is_empty());p.cancel();assert!(!f.scope.is_open());}
#[test]fn group_management_uninstalled_descriptor_schema_stays_absent_and_cannot_admit(){let f=Fixture::new(true);assert_eq!(intent(&f,&"a".repeat(32),Op::Disband).err(),Some("app_account_group_management_not_installed"));let n:i64=f.temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_relation_intents",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(n,0);}
#[test]fn group_management_concurrent_member_and_management_preparations_have_exactly_one_durable_owner(){
 for management_first in [false,true]{let f=installed();let config=Arc::new(f.temp.database.with_conn(|c|RelationConfiguration::capture(c,f.run.line_id(),1,Some(&f.scope))).unwrap());let member=Arc::new(RelationMessage::capture(&f.scope,None,&[relation(b"1_2")],&[],&[],&"c".repeat(32),policy()).unwrap());let group=Arc::new(RelationMessage::capture_management(&f.scope,b"1-2",Op::Disband,&[],&"d".repeat(32),gpolicy()).unwrap());let order=if management_first{[group,member]}else{[member,group]};let barrier=Arc::new(std::sync::Barrier::new(3));let mut jobs=Vec::new();
 for m in order{let db=f.temp.database.clone();let run=f.run.clone();let owner=f.owner.clone();let scope=f.scope.clone();let gate=f.gate.clone();let cfg=config.clone();let ready=barrier.clone();jobs.push(std::thread::spawn(move||{ready.wait();RelationIntent::capture(db,run,owner,scope,m,cfg,gate,Instant::now()+Duration::from_secs(30))}));}barrier.wait();let results=jobs.into_iter().map(|j|j.join().unwrap()).collect::<Vec<_>>();assert_eq!(results.iter().filter(|r|r.is_ok()).count(),1);assert_eq!(results.iter().filter(|r|matches!(r,Err("app_account_relation_preparing"))).count(),1);let count:i64=f.temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_relation_intents WHERE state=0",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(count,1);drop(results);assert!(f.temp.database.with_conn(|c|n::relation_journal::intent_history(c,f.run.line_id(),128)).unwrap().iter().all(|r|r.state=="not_sent"));}
}
#[test]fn group_management_missing_or_orphaned_descriptor_never_lifts_shared_unknown(){let f=installed();let IntentAdmission::Fresh(i)=intent(&f,&"a".repeat(32),Op::Disband).unwrap()else{panic!()};f.temp.database.with_conn(|c|c.execute("DELETE FROM app_voice_group_write_operations",[]).map_err(|_|"fixture")).unwrap();assert_eq!(intent(&f,&"b".repeat(32),Op::Disband).err(),Some("app_account_relation_storage_failed"));assert!(f.temp.database.with_conn(|c|n::relation_journal::intent_history(c,f.run.line_id(),128)).is_err());drop(i);let state:i64=f.temp.database.with_conn(|c|c.query_row("SELECT state FROM app_voice_relation_intents",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(state,0);}
#[test]fn group_management_decoder_rejects_cross_operation_truncation_trailing_and_remote_result(){let f=installed();let mut w=Writer::new();w.boolean(true).unwrap();w.i64(i64::MIN).unwrap();w.i64(i64::MAX).unwrap();w.bytes(b"").unwrap();let bytes=w.finish();for end in 0..bytes.expose_to_transport().len(){assert!(gm::decode(&f.scope,Op::Disband,0,&bytes.expose_to_transport()[..end]).is_err());}assert!(gm::decode(&f.scope,Op::SetProperties,0,bytes.expose_to_transport()).is_err());assert!(gm::decode(&f.scope,Op::Disband,1,bytes.expose_to_transport()).is_err());assert!(gm::decode(&f.scope,Op::Disband,0,&[0,1,0,0,0,0]).is_err());assert_eq!(f.scope.native_rpc_resources(),(0,0));}
